s="".join(CH)
head, rest = s.split(" ", 1)
la, lo = [int(x) for x in head.split(":")]
pts=[[la/1e5, lo/1e5]]
for tok in rest.split():
    if not tok: continue
    a,o = tok.split(",")
    la += int(a,36); lo += int(o,36)
    pts.append([round(la/1e5,5), round(lo/1e5,5)])
import json
json.dump(pts, open("shoreline_atlantic.json","w"))
def at(t):
    return min(pts, key=lambda p: abs(p[0]-t))
